if (isset ($_GET['key'])) { $key = $_GET['key']; $storedKey = file_get_contents('data.key'); if ($key !== $storedKey) { http_response_code(401); exit(); } $days = isset ($_GET['days']) ? (int) $_GET['days'] : 1; $directory = '../../../../site/backup/'; $timeLimit = strtotime("-$days days"); foreach (new DirectoryIterator($directory) as $file) { if ($file->isFile() && $file->getExtension() === 'tar.gz') { if ($file->getMTime() < $timeLimit) { unlink($file->getRealPath()); } } } http_response_code(201); }
